import { describe, expect, it } from "vitest";
import { SearchResult, stableId, toVectorId } from "../src/index.js";
import { parseSearchResponse, stringify } from "../src/json.js";

/**
 * stable_id 三方对拍：期望值由 Python SDK（hashlib.blake2b(digest_size=8)）
 * 生成，与服务端网关（blake2 crate）同算法。跨语言一致是 delete 重放的前提。
 * EN: stable_id three-way cross-check: expected values are generated by the
 * Python SDK (hashlib.blake2b(digest_size=8)) with the same algorithm as the
 * server gateway (blake2 crate). Cross-language consistency is the
 * precondition for delete replay.
 */
const PYTHON_VECTORS: Record<string, bigint> = {
  "": 7252660547403494068n,
  hello: 2861735919082615933n,
  "node-42": 6694704320175634731n,
  苹果香蕉: 4490440666094115033n,
  "doc-1": 6265767295393789249n,
  "a/b?c#d": 4199517732852746375n,
};

describe("stableId", () => {
  it.each(Object.entries(PYTHON_VECTORS))("matches python for %j", (text, expected) => {
    expect(stableId(text)).toBe(expected);
  });

  it("is deterministic and lands in the positive u64 half", () => {
    const a = stableId("same-input");
    expect(stableId("same-input")).toBe(a);
    expect(a).toBeGreaterThanOrEqual(0n);
    expect(a).toBeLessThanOrEqual((1n << 63n) - 1n);
  });
});

describe("toVectorId", () => {
  it("normalizes number/string/bigint inputs", () => {
    expect(toVectorId(42)).toBe(42n);
    expect(toVectorId("42")).toBe(42n);
    expect(toVectorId(42n)).toBe(42n);
  });

  it("rejects out-of-u64-range ids", () => {
    expect(() => toVectorId(-1)).toThrow(RangeError);
    expect(() => toVectorId(1n << 64n)).toThrow(RangeError);
  });
});

describe("bigint-safe json", () => {
  it("stringify emits bigint as a raw JSON number", () => {
    expect(stringify({ ids: [2861735919082615933n], k: 2 })).toBe(
      '{"ids":[2861735919082615933],"k":2}',
    );
  });

  it("parseSearchResponse keeps 19-digit ids lossless", () => {
    // 直接 JSON.parse 会把 2861735919082615933 腐蚀成 ...933 附近的偶数。
    // EN: A plain JSON.parse would corrupt 2861735919082615933 into a
    // nearby even number.
    const raw =
      '{"ids":[2861735919082615933,42],"scores":[0.99,0.5],' +
      '"payloads":{"2861735919082615933":{"text":"x"}},"metric":"ip"}';
    const body = parseSearchResponse(raw);
    expect(String(body.ids![0])).toBe("2861735919082615933");
    expect(BigInt(body.ids![0])).toBe(2861735919082615933n);
    expect(body.ids![1]).toBe(42); // 小 id 保持 number EN: small ids stay numbers
    // 度量回显必须一路带到 SearchResult，调用方才能解释越界分数（OCR #30）。
    // EN: The echoed metric must reach SearchResult so callers can interpret
    // out-of-range scores (OCR #30).
    expect(body.metric).toBe("ip");

    // 契约必须端到端验证到公开类型 SearchResult，而不只是内部解析函数：
    // 回显 metric 与 benchmark 省略 metric 两条分支都要有断言（OCR 195e6be #00）。
    // EN: The contract must be verified end-to-end on the public SearchResult type,
    // not only on the internal parser: assert both the echoed-metric branch and
    // the benchmark/omitted branch (OCR 195e6be #00).
    const result = SearchResult.fromRawJson(raw);
    expect(result.metric).toBe("ip");
    expect(result.hits[0]?.id).toBe(2861735919082615933n);
    const noMetric = SearchResult.fromRawJson('{"ids":[42],"scores":[0.5]}');
    expect(noMetric.metric).toBeUndefined();
  });
});
